---@type PixyWorldGrandMarchGameLevelConstantsUtil
local util = get_or_create_global_variable('Quest/Main/PixyWorld/GrandMarch/Game/ConstantsUtil')

local type_const = util.type_const
local create_clip = util.create_clip
local create_sub_clip = util.create_sub_clip
local create_clip_bundle = util.create_clip_bundle
local generate_sub_clip_by_function = util.generate_sub_clip_by_function

---@type PixyWorldGrandMarchGameLevelConstantsSceneBundleGenerator
local scene_bundle_generator = get_or_create_global_variable(
		'Quest/Main/PixyWorld/GrandMarch/Game/LevelConstants/SceneBundleGenerator')

local pattern_args = {
	--D, E, F, G 위치에 플라워들이 중앙 플레이어 위치를 바라보는 상태로 smile, idle로 배치된 상태.
	--폭탄 낙하 연출
	--0초 ~ 0.5초 : 지정된 지점에 어택 레인지 생성 +
	--D, E, F, G 의 플라워들 우측 폭탄꽃에 배치된 폭탄을 right, smile, hold로 들어올림.
	--0.5초 ~ 1초 : Y축 상단에서부터 지정된 지점까지 낙하함 +
	--D, E, F, G 의 플라워들 홀드한 폭탄을 붉은색 자신의 알파벳 지점을 향해 0.5초의 시간동안 던져지도록 함.
	--1초 ~ 1.5초 : 폭탄 도착한 뒤, 폭파 후 1.5초가 될 때까지 대기 + 대기 시간동안 폭탄꽃에 폭탄 스케일 상승하며 생성됨.
	--1. (31초 ~ 43초) : D, E, F, G 위치에 1.5초 간격으로 폭탄 낙하 연출이 실행 반복(총 8회)
	normal = {
		characters = {
			upper = {
				'bomb_upper_1',
				'bomb_upper_2',
				'bomb_upper_3',
				'bomb_upper_4',
			},
			lower = {
				'bomb_lower_1',
				'bomb_lower_2',
				'bomb_lower_3',
				'bomb_lower_4',
			},
			all = {
				'bomb_upper_1',
				'bomb_upper_2',
				'bomb_upper_3',
				'bomb_upper_4',

				'bomb_lower_1',
				'bomb_lower_2',
				'bomb_lower_3',
				'bomb_lower_4',
			}
		},
		start_bit = 62,
		repeat_count = 8,
	},
	--A ~ G 위치에 플라워들이 중앙 플레이어를 위치를 바라보는 상태로 smile, idle로 배치된 상태.
	--폭탄 낙하 연출
	--0초 ~ 0.5초 : 지정된 지점에 어택 레인지 생성 +
	--A ~ G 의 플라워들 우측 폭탄꽃에 배치된 폭탄을 right, smile, hold로 들어올림.
	--0.5초 ~ 1초 : Y축 상단에서부터 지정된 지점까지 낙하함. +
	--A ~ G 의 플라워들 홀드한 폭탄을 붉은색 자신의 알파벳 지점을 향해 0.5초의 시간동안 던져지도록 함.
	--1초 ~ 1.5초 : 폭탄 도착한 뒤, 폭파 후 1.5초가 될 때까지 대기 + 대기 시간동안 폭탄꽃에 폭탄 스케일 상승하며 생성됨.
	--1. (21초 ~ 30초) : A ~ G 위치에 1.5초 간격으로 폭탄 낙하 연출이 실행 반복(총 6회 / 22초부터 폭발이 시작)
	hard = {
		characters = {
			upper = {
				'bomb_a_upper',
				'bomb_b_upper',
				'bomb_c_upper',
				'bomb_d_upper',
				'bomb_e_upper',
				'bomb_f_upper',
				'bomb_g_upper',
			},
			lower = {
				'bomb_a_lower',
				'bomb_b_lower',
				'bomb_c_lower',
				'bomb_d_lower',
				'bomb_e_lower',
				'bomb_f_lower',
				'bomb_g_lower',
			},
			all = {
				'bomb_a_upper',
				'bomb_b_upper',
				'bomb_c_upper',
				'bomb_d_upper',
				'bomb_e_upper',
				'bomb_f_upper',
				'bomb_g_upper',

				'bomb_a_lower',
				'bomb_b_lower',
				'bomb_c_lower',
				'bomb_d_lower',
				'bomb_e_lower',
				'bomb_f_lower',
				'bomb_g_lower',
			}
		},
		start_bit = 42,
		repeat_count = 6,
	}
}

local attack_range_preset_key = 'bomb_circle'
local fx_preset_key = 'bomb_explosion'
local explosion_radius = 1.5

local create_pattern = function(args)
	local characters = args.characters

	local init = {
		create_clip_bundle(-1, nil, {
			generate_sub_clip_by_function('field_object.bomb.instantiate', characters.all, function(key, value)
				return {
					name = value,
					position = value .. '_spawn'
				}
			end),

			create_sub_clip('character.group.register', {
				characters = characters.all,
				spec_name = 'flower',
			}),

			generate_sub_clip_by_function('character.single.set', characters.upper, function(key, value)
				return {
					name = value,
					position = value,
					direction = 'down',
					emotion = 'smile',
				}
			end),

			generate_sub_clip_by_function('character.single.set', characters.lower, function(key, value)
				return {
					name = value,
					position = value,
					direction = 'up',
				}
			end),

			create_sub_clip('fx.preload', {
				preset_key = fx_preset_key,
				spec = {
					name = 'FX_Explosion_Bomb_new'
				}
			}),

			create_sub_clip('attack_range.preload', {
				preset_key = attack_range_preset_key,
				preset = {
					shape = type_const.attack_range_shape.circle,
					color_key = 'red',
					radius = explosion_radius,
					show_type = attack_range_show_type.none,
				},
				min_count = #characters.all,
			})
		})
	}

	local dispose = {
		create_clip_bundle(-1, nil, {
			generate_sub_clip_by_function('field_object.bomb.dispose', characters.all, function(key, value)
				return {
					name = value,
				}
			end),
		}),
		scene_bundle_generator.bundle.create_group_dispose(characters.all)
	}

	local game_groups = {}

	--해당 연출 참고 부탁드립니다 :  가디언테일즈 단편집 - 크리스마스 캐럴 클리어  / 크리스마스 단편 서브 이벤트 기획서
	for type_name, names in pairs(characters) do
		if type_name == 'all' then
			goto continue
		end

		local throw_direction = lua_helper.get_conditional_value(type_name == 'upper', 'down', 'up')

		for _, bomb_name in pairs(names) do
			game_groups[bomb_name] = scene_bundle_generator.group.create_throw_bomb({
				start_bit = args.start_bit,
				hold_up_duration = 1,
				bomb_move_duration = 1,
				bomb_spawn_duration = 1,
			}, {
				name = bomb_name,
				throw_direction = throw_direction
			}, {
				name = bomb_name,
				spawn_position = bomb_name .. '_spawn',
				hold_up_position = bomb_name .. '_hold_up',
				fall_position = bomb_name .. '_fall',
				explosion_radius = explosion_radius,
			}, {
				attack_range_preset_key = attack_range_preset_key,
				fx_preset_key = fx_preset_key,
			}, args.repeat_count)
		end

		:: continue ::
	end

	return {
		init = init,
		game = util.merge_groups(game_groups),
		dispose = dispose,
	}
end

local cached_patterns = {}

return {
	generate = function(key)
		if cached_patterns[key] == nil then
			local args = pattern_args[key]

			cached_patterns[key] = create_pattern(args)
		end

		return cached_patterns[key]
	end
}

