local create_bugs_info = function(start_bit, name, offsets)
	local names = {}

	for i = 1, #offsets do
		names[i] = name .. '_' .. i
	end

	return {
		spec_name = 'bug',
		name = name,
		names = names,
		start_bit = start_bit,
		spawn_pos = name,
		offsets = offsets,
	}
end

local create_flying_bugs_info = function(start_bit, name, offsets, waypoint_count, player_crash_calculator)
	local names = {}

	for i = 1, #offsets do
		names[i] = name .. '_' .. i
	end

	local waypoints = nil

	if waypoint_count > 0 then
		waypoints = {}

		for i = 1, waypoint_count - 1 do
			waypoints[i] = name .. '_move_' .. i
		end

		-- 시작 지점과 끝 지점은 같아야 함.
		waypoints[waypoint_count] = name
	end

	return {
		spec_name = 'flying_bug',
		name = name,
		names = names,
		start_bit = start_bit,
		spawn_pos = name,
		offsets = offsets,

		waypoints = waypoints,
		player_crash_calculator = player_crash_calculator,
	}
end

local create_mother_bug_info = function(start_bit, name, split_offsets)
	local child_names = {}

	for i = 1, #split_offsets do
		child_names[i] = name .. '_child_' .. i
	end

	return {
		spec_name = 'mother_bug',
		name = name,
		start_bit = start_bit,
		spawn_pos = name,

		split_offsets = split_offsets,
		child_names = child_names
	}
end

