local fx_dead_preset_key = 'enemy_dead'

local create_default_dead_clips = function(character_name, world_pos, start_bit, _)
	local values = {}

	values[#values + 1] = create_clip(start_bit, nil, 'fx.time_limited', {
		preset_key = fx_dead_preset_key,
		world_pos = world_pos,
	})

	values[#values + 1] = create_clip(start_bit, nil, 'character.single.reset', {
		name = character_name,
		reset_offset = true,
	})

	values[#values + 1] = create_clip(start_bit, nil, 'character.single.set', {
		name = character_name,
		position = 'nowhere',
	})

	values[#values + 1] = create_clip(start_bit, nil, 'audio.sfx.one_shot', {
		name = '01_arcade_get_02'
	})

	values[#values + 1] = create_clip(start_bit, nil, 'audio.sfx.one_shot', {
		name = '02_flower_hit_01',
		volume = 0.3
	})

	return values
end

local create_split_dead_clips = function(character_name, world_pos, start_bit, origin_info)
	local values = create_default_dead_clips(character_name, world_pos, start_bit)
	local spawn_end_bit = start_bit + 0.5

	values[#values + 1] = create_clip(start_bit, spawn_end_bit, 'character.group.set', {
		characters = origin_info.child_names,
		common = {
			world_pos = world_pos
		}
	})

	values[#values + 1] = create_clip(start_bit, spawn_end_bit, 'character.group.jump', {
		characters = origin_info.child_names,
		height = 2,
	})

	values[#values + 1] = create_clip(spawn_end_bit, nil, 'character.group.add_crasher', {
		characters = origin_info.child_names,
	})

	for i = 1, #origin_info.child_names do
		local name = origin_info.child_names[i]

		values[#values + 1] = create_clip(start_bit, spawn_end_bit, 'character.single.simple_move', {
			name = name,
			world_pos = world_pos + origin_info.split_offsets[i]
		})

		values[#values + 1] = create_clip(start_bit, origin_info.game_end_bit, 'character.enemy.while_dead', {
			name = name,
			on_dead = {
				create_game_clips = create_default_dead_clips
			}
		})
	end

	return values
end

