	}

	for _, info in pairs(args.infos) do
		local target_container = characters[info.spec_name]

		if info.names ~= nil then
			for i = 1, #info.names do
				target_container[#target_container + 1] = info.names[i]
			end
		else
			target_container[#target_container + 1] = info.name

			for i = 1, #info.child_names do
				characters.bug[#characters.bug + 1] = info.child_names[i]
			end
		end
	end

	local init = {
		create_clip_bundle(-1, nil, {
			create_sub_clip('fx.preload', {
				preset_key = fx_dead_preset_key,
				spec = {
					name = 'fx_pw_grand_march_enemy_dead',
					scale = 0.2,
				}
			}),
		}),
	}

	local log_text = 'Required Bug NPC Counts\n'

	for spec_name, group_characters in pairs(characters) do
		local anim = lua_helper.get_conditional_value(spec_name == 'flying_bug', 'fly', nil)

		log_text = log_text .. spec_name .. ' -> ' ..  #group_characters .. '\n'

		init[#init + 1] = create_clip_bundle(-1, nil, {
			create_sub_clip('character.group.register', {
				characters = group_characters,
				spec_name = spec_name,
			}),
			create_sub_clip('character.group.set', {
				characters = group_characters,
				common = {
					direction = 'left',
					anim = anim,
					active_state = active_state_type.visible,
					force_update_spine = true,
				}
			}),
		})
	end

	logger_util.log(log_text)

	for i = 1, #args.infos do
		local info = args.infos[i]

		if info.names ~= nil then
			for j = 1, #info.names do
				init[#init + 1] = create_clip(-1, nil, 'character.single.offset', {
					name = info.names[j],
					offset = info.offsets[j]
				})
			end
		end
	end

	local game_groups = {}

	for i = 1, #args.infos do
		local info = args.infos[i]
		local fall_end_bit = info.start_bit + 2

		if info.names ~= nil then
			for _, name in pairs(info.names) do
				local group = {
					create_clip(info.start_bit, fall_end_bit, 'character.enemy.spawn_fall', {
						name = name,
						position = info.spawn_pos
					}),
					create_clip(fall_end_bit, args.common.game_end_bit, 'character.enemy.while_dead', {
						name = name,
						on_dead = {
							create_game_clips = create_default_dead_clips,
						},
						player_crash_calculator = info.player_crash_calculator,
					})
				}

				if info.waypoints ~= nil then
					group[#group + 1] = create_clip(fall_end_bit, args.common.game_end_bit,
							'character.enemy.move_loop', {
								name = name,
								waypoints = info.waypoints,
								-- 실제 속도는 2지만, 비트 단위로 계산하기 때문에 1로 넣음
								speed = 1
							})
				end

				game_groups[name] = group
			end
		else
			local group = {
				create_clip(info.start_bit, fall_end_bit, 'character.enemy.spawn_fall', {
					name = info.name,
					position = info.spawn_pos
				}),
				create_clip(fall_end_bit, args.common.game_end_bit, 'character.enemy.while_dead', {
					name = info.name,
					origin_info = {
						child_names = info.child_names,
						split_offsets = info.split_offsets,
						game_end_bit = args.common.game_end_bit,
					},
					on_dead = {
						create_game_clips = create_split_dead_clips,
					}
				})
			}

			game_groups[info.name] = group
		end
	end

	local dispose = {
		scene_bundle_generator.bundle.create_group_dispose(characters.bug, 'left'),
		scene_bundle_generator.bundle.create_group_dispose(characters.flying_bug, 'left'),
		scene_bundle_generator.bundle.create_group_dispose(characters.mother_bug, 'left'),
	}

	return {
		init = init,
		game = util.merge_groups(game_groups),
		dispose = dispose,
	}
end

local cached_patterns = {}

return {
	generate = function(key)
		if cached_patterns[key] == nil then
			local args = pattern_args[key]

			cached_patterns[key] = create_pattern(args)
		end

		return cached_patterns[key]
	end
}

