---@type PixyWorldGrandMarchGameLevelConstantsUtil
local util = get_or_create_global_variable('Quest/Main/PixyWorld/GrandMarch/Game/ConstantsUtil')

local type_const = util.type_const
local create_clip = util.create_clip
local create_sub_clip = util.create_sub_clip
local create_clip_bundle = util.create_clip_bundle
local generate_sub_clip_by_function = util.generate_sub_clip_by_function

---@type PixyWorldGrandMarchGameLevelConstantsSceneBundleGenerator
local scene_bundle_generator = get_or_create_global_variable(
		'Quest/Main/PixyWorld/GrandMarch/Game/LevelConstants/SceneBundleGenerator')

--1. 최초 파이프 위치에 그룹 A ~ F down, idle, hide(임시 : prostrate) 상태로 배치됨.
local pattern_args = {
	casement = {
		groups = {
			--2. (63초 ~ 69.5초) : A 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(63.5초)
			--이후 69초 A 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후 도착한 위치에서 down idle, hide 상태로 변경.
			--66초 ~ 67.5초 / 67.5초 ~ 69초(각 시점에 A 그룹에 아래의 동작 수행)
			--그룹 A 0.5초간 위, 아래로 각각 smile, sing(upper)를 실행하여 통로를 연다.
			--0.5초 대기.
			--그룹 A 0.5초간 위, 아래로 각각 smile, sing(upper)를 실행하여 통로를 닫는다.
			a = {
				pop_out_bit = 0,
				hide_bit = 12,
			},
			--4. (64초 ~ 70.5초) : C 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(64.5)
			--이후 70초 C 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후 도착한 위치에서 down idle, hide 상태로 변경.
			--66초 ~ 67.5초 / 67.5초 ~ 69초(각 시점에 C 그룹에 아래의 동작 수행)
			--그룹 C 0.5초간 위, 아래로 각각 smile, sing(upper)를 실행하여 통로를 연다.
			--0.5초 대기.
			--그룹 C 0.5초간 위, 아래로 각각 smile, sing(upper)를 실행하여 통로를 닫는다.
			c = {
				pop_out_bit = 2,
				hide_bit = 14,
			},
			d = {
				pop_out_bit = 4,
				hide_bit = 16,
			},
			f = {
				characters = {
					'right_3',
					'right_4',
				},
				-- 얘는 Pop Out을 하지 않을 것임
				pop_out_bit = nil,
				hide_bit = 18,
			},
		},
		common = {
			offsets = {
				vector(0, 0, 0.5),
				vector(0, 0, -0.5),
			},
			pop_out_duration = 1,
			hide_in_duration = 1,
			move_infos = {
				{
					type = 'open',
					start_bit = 6,
					end_bit = 8
				},
				{
					type = 'close',
					start_bit = 10,
					end_bit = 12
				},
			}
		}
	},
	block = {
		groups = {
			--3. (63.5초 ~ 70.0초) : B 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(64)
			--이후 69.5초 B 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후
			--도착한 위치에서 down idle, hide 상태로 변경.
			b = {
				start_bit_offset = 1,
				hide_start_delay = 12,
			},
			--6. (65.5초 ~ 72초) : E 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(66)
			--이후 71.5초 E 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후
			--도착한 위치에서 down idle, hide 상태로 변경.
			e = {
				start_bit_offset = 5,
				hide_start_delay = 12,
			},
		},
		common = {
			offsets = {
				vector(0, 0, 2.5),
				vector(0, 0, 1.5),
				vector(0, 0, -1.5),
				vector(0, 0, -2.5),
			},
			pop_out_duration = 1,
			hide_in_duration = 1,
		}
	}
}

local patterns = {}

for group_key, args in pairs(pattern_args.casement.groups) do
	local group_name = 'accel_' .. group_key
	local characters = args.characters
	local common = pattern_args.casement.common

	if characters == nil then
		characters = {}

		for i = 1, #common.offsets do
			characters[i] = group_name .. '_' .. i
		end
	end

	local init = nil

	if args.pop_out_bit ~= nil then
		init = {
			--1. 최초 파이프 위치에 그룹 A ~ F down, idle, hide(임시 : prostrate) 상태로 배치됨.
			create_clip_bundle(-1, nil, {
				create_sub_clip('character.group.register', {
					characters = characters,
					spec_name = 'flower'
				}),
				generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
					return {
						name = value,
						offset = common.offsets[key],
					}
				end),
				scene_bundle_generator.sub.create_group_hide_init(characters, group_name)
			})
		}
	end

	local pop_out_end_bit

	if args.pop_out_bit ~= nil then
		pop_out_end_bit = args.pop_out_bit + common.pop_out_duration
	else
		pop_out_end_bit = common.move_infos[1].start_bit
	end

	local game = {}

	if args.pop_out_bit ~= nil then
		--2. (63초 ~ 69.5초) : A 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(63.5초)
		game[#game + 1] = scene_bundle_generator.bundle.create_group_pop_out(args.pop_out_bit, pop_out_end_bit,
				characters, group_name .. '_land')
	end

	game[#game + 1] = create_clip_bundle(pop_out_end_bit, args.hide_bit, {
		create_sub_clip('character.group.reset', {
			characters = characters,
			common = {
				reset_offset = true,
			}
		}),
		create_sub_clip('character.group.set_async', {
			characters = characters,
			set_common = {
				direction = 'left',
				emotion = 'smile',
				anim = { name = 'sing', upper = true },
			},
			reset_common = {
				remove_emotion = true,
				remove_anim_type = type_const.remove_anim_type.upper,
			},
		}),
	})

	for i = 1, #common.move_infos do
		local info = common.move_infos[i]

		game[#game + 1] = create_clip_bundle(info.start_bit, info.end_bit, {
			generate_sub_clip_by_function('character.single.simple_move', characters, function(key, value)
				return {
					name = value,
					position = group_name .. '_' .. key .. '_' .. info.type,
					use_walk = true,
				}
			end)
		})
	end

	game[#game + 1] = create_clip_bundle(args.hide_bit, nil, {
		generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
			return {
				name = value,
				offset = common.offsets[key],
			}
		end),
	})

	--이후 69초 A 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후
	--도착한 위치에서 down idle, hide 상태로 변경.
	game[#game + 1] = scene_bundle_generator.bundle.create_group_hide_in(args.hide_bit,
			args.hide_bit + common.hide_in_duration, characters, group_name, 'left')

	local dispose = nil

	if args.pop_out_bit ~= nil then
		dispose = {
			scene_bundle_generator.bundle.create_group_dispose(characters)
		}
	end

	patterns[#patterns + 1] = {
		init = init,
		game = game,
		dispose = dispose,
	}
end

for group_key, args in pairs(pattern_args.block.groups) do
	local group_name = 'accel_' .. group_key
	local characters = {}
	local common = pattern_args.block.common

	for i = 1, #common.offsets do
		characters[i] = group_name .. '_' .. i
	end

	local init = {
		--1. 최초 파이프 위치에그룹 A ~ F down, idle, hide(임시 : prostrate) 상태로 배치됨.
		create_clip_bundle(-1, nil, {
			create_sub_clip('character.group.register', {
				characters = characters,
				spec_name = 'flower'
			}),

			generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
				return {
					name = value,
					offset = common.offsets[key],
				}
			end),
			scene_bundle_generator.sub.create_group_hide_init(characters, group_name)
		})
	}

	local pop_out_end_bit = args.start_bit_offset + common.pop_out_duration
	local hide_start_bit = args.start_bit_offset + args.hide_start_delay

	local game = {
		--3. (63.5초 ~ 70.0초) : B 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.(64)
		scene_bundle_generator.bundle.create_group_pop_out(args.start_bit_offset, pop_out_end_bit,
				characters, group_name .. '_land'),

		create_clip_bundle(pop_out_end_bit, hide_start_bit, {
			create_sub_clip('character.group.set_async', {
				characters = characters,
				set_common = {
					direction = 'left',
					emotion = 'sing',
					anim = 'sing',
				},
				reset_common = {
					remove_emotion = true,
					remove_anim_type = type_const.remove_anim_type.normal,
				},
			}),
		}),
		--이후 69.5초 B 그룹 플라워 left, smile, hide_in을 실행하여 0.5초 안에 좌측으로 이동한 후
		--도착한 위치에서 down idle, hide 상태로 변경.
		scene_bundle_generator.bundle.create_group_hide_in(hide_start_bit,
				hide_start_bit + common.hide_in_duration, characters, group_name, 'left'),
	}

	local dispose = {
		scene_bundle_generator.bundle.create_group_dispose(characters)
	}

	patterns[#patterns + 1] = {
		init = init,
		game = game,
		dispose = dispose,
	}
end

local result = util.merge_patterns(patterns)

util.add_delay_to_group(result.game, 126)

return result

