local create_pattern = function(group_key, args)
	local group_name = 'pond_' .. group_key
	local characters = args.characters

	local init = {
		create_clip_bundle(-1, nil, {
			create_sub_clip('character.group.register', {
				characters = characters,
				spec_name = 'flower'
			}),
			generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
				return {
					name = value,
					offset = offsets[key]
				}
			end),
			scene_bundle_generator.sub.create_group_hide_init(characters, group_name),
		}),
	}

	local dispose = {
		scene_bundle_generator.bundle.create_group_dispose(characters),
	}

	local game = {
		--2. (73초 ~ 74초) : A ~ D 그룹 right, smile, hide_out(임시 : jump)를 실행하여 2타일 우측으로 이동한 후,
		scene_bundle_generator.bundle.create_group_pop_out(0, 2,
				characters, group_name .. '_land'),

		create_clip(2, nil, 'character.group.set', {
			characters = characters,
			common = {
				emotion = 'sing',
			},
		}),
	}

	local moves = {}

	for i = 1, #args.move_info do
		local info = args.move_info[i]
		local end_bit = info.end_bit or args.move_info[i + 1].start_bit
		local anim_name = lua_helper.get_conditional_value(info.use_dance, 'dance', 'sing')
		local reset_common = nil

		-- 마지막에는 Main쪽에서 조작해주도록 따로 지우지 않음
		if i < #args.move_info then
			reset_common = {
				remove_anim_type = type_const.remove_anim_type.upper,
			}
		end

		moves[i] = create_clip_bundle(info.start_bit, end_bit, {
			create_sub_clip('character.group.set_async', {
				characters = characters,
				set_common = {
					direction = info.direction,
					anim = { name = anim_name, upper = true }
				},
				reset_common = reset_common
			}),
			create_sub_clip('character.group.move', {
				characters = characters,
				waypoints = {
					group_name .. '_move_' .. i,
				},
				use_walk = true,
			}),
		})
	end

	return {
		init = init,
		game = util.merge_groups({
			game,
			moves,
		}),
		dispose = dispose
	}
end

local patterns = {}

for group_key, group_info in pairs(group_args) do
	patterns[group_key] = create_pattern(group_key, group_info)
end

local result = util.merge_patterns(patterns)

util.add_delay_to_group(result.game, 146)

return result

