			scene_bundle_generator.bundle.create_group_hide_in(hide_in_start_bit, hide_in_end_bit,
					characters, group_name .. '_end')
		}

		local jump_tile_name = nil

		if info.jump_tile_name == true  then
			jump_tile_name = group_name
		elseif type_util.is_string(info.jump_tile_name) then
			jump_tile_name = info.jump_tile_name
		end

		if jump_tile_name ~= nil then
			game = util.merge_groups({
				game,
				{
					create_clip(jump_start_bit, jump_start_bit + 2, 'field_object.common.play_anim', {
						name = jump_tile_name,
						anim_name = 'on',
						reset_anim_name = 'off',
					})
				}
			})
		end

		local dispose = {
			scene_bundle_generator.bundle.create_group_dispose(characters)
		}

		patterns[group_key] = {
			init = init,
			game = game,
			dispose = dispose,
		}
	end

	local result = util.merge_patterns(patterns)

	util.add_delay_to_group(result.game, args.common.start_delay)

	return result
end

local cached_patterns = {}

return {
	generate = function(key)
		if cached_patterns[key] == nil then
			local args = pattern_args[key]

			cached_patterns[key] = create_pattern(args)
		end

		return cached_patterns[key]
	end
}

