local create_pattern = function(args)
	local patterns = {}

	for group_key, info in pairs(args.groups) do
		local characters = {}
		local group_name = 'pipe_dance_' .. group_key

		for i = 1, #info.offsets do
			local name = group_name .. '_' .. i

			characters[i] = name
		end

		--최초 파이프 위치에 그룹 A ~ C down, idle, hide(임시 : prostrate) 상태로 배치됨.
		local init = {
			create_clip_bundle(-1, nil, {
				create_sub_clip('character.group.register', {
					characters = characters,
					spec_name = 'flower'
				}),

				generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
					return {
						name = value,
						offset = info.offsets[key]
					}
				end),

				scene_bundle_generator.sub.create_group_hide_init(characters, group_name),
			})
		}

		local game = {
			--1. (30.5초 ~ 31.5초) : A ~ F 그룹에 1초간 12마리의 플라워가 배치된 파이프에서부터
			--right, smile, hide_out(임시 : jump)를 실행하여 2타일 우측에 착지 후,
			scene_bundle_generator.bundle.create_group_pop_out(0, args.common.pop_out_duration,
					characters, group_name .. '_land'),
			create_clip(args.common.pop_out_duration, nil, 'character.group.set', {
				characters = characters,
				common = {
					emotion = 'sing',
				},
			})
		}

		local wp_index = 1

		if args.common.start_with_sing then
			game[#game + 1] = create_clip_bundle(info.move_info.start_delays[1], info.move_info.start_delays[2], {
				create_sub_clip('character.group.set_async', {
					characters = characters,
					set_common = {
						direction = 'right',
						anim = { name = 'sing', upper = true },
					},
					reset_common = {
						remove_anim_type = type_const.remove_anim_type.upper,
					}
				}),

				create_sub_clip('character.group.move', {
					characters = characters,
					waypoints = {
						group_name .. '_move_1'
					},
					use_walk = true,
				})
			})

			wp_index = 2
		end

		game[#game + 1] = create_clip_bundle(info.move_info.start_delays[wp_index], info.move_info.start_delays[wp_index + 1], {
			create_sub_clip('character.group.set_async', {
				characters = characters,
				set_common = {
					anim = { name = 'dance', upper = true },
				},
				reset_common = {
					remove_anim_type = type_const.remove_anim_type.upper,
				}
			}),
			create_sub_clip('character.group.set_on_end', {
				characters = characters,
				common = {
					anim = { name = 'sing', upper = true },
				},
			}),
		})

		for i = wp_index, #info.move_info.start_delays do
			local start_delay = info.move_info.start_delays[i]
			local end_delay = info.move_info.start_delays[i + 1] or info.move_info.end_delay

			game[#game + 1] = create_clip(start_delay, end_delay, 'character.group.move', {
				characters = characters,
				waypoints = {
					group_name .. '_move_' .. i
				},
				use_walk = true,
			})
		end

		--6. (37.5초) : E 그룹 현재 위치에 left, smile, get 자세 실행 후 정지.
		game[#game + 1] = create_clip_bundle(info.move_info.end_delay, info.jump_delay, {
			create_sub_clip('character.group.reset', {
				characters = characters,
				common = {
					remove_emotion = true,
					remove_anim_type = type_const.remove_anim_type.upper,
				},
			}),

			create_sub_clip('character.group.set_async', {
				characters = characters,
				set_common = {
					direction = info.stop_direction,
					anim = 'get',
					emotion = 'smile',
				},
				reset_common = {
					remove_anim_type = type_const.remove_anim_type.normal,
				}
			}),
		})

		--10. (43.5초 ~ 44초) : E 0.5초간 플라워가 배치된 파이프에 right, smile, hide_in(임시 : jump)를 실행.
		--1타일 우측에 착지하여 down, idle, hide(임시 : prostrate) 실행 후 유지.
		game[#game + 1] = scene_bundle_generator.bundle.create_group_hide_in(
				info.jump_delay, info.jump_delay + args.common.hide_in_duration,
				characters, group_name .. '_end')

		local dispose = {
			scene_bundle_generator.bundle.create_group_dispose(characters),
		}

		patterns[group_key] = {
			init = init,
			game = game,
			dispose = dispose,
		}
	end

	--최초 파이프 위치에 그룹 A ~ C down, idle, hide(임시 : prostrate) 상태로 배치됨.

	--1. (30.5초 ~ 31.5초) : A ~ F 그룹에 1초간 12마리의 플라워가 배치된 파이프에서부터
	--right, smile, hide_out(임시 : jump)를 실행하여 2타일 우측에 착지 후,
	--전체 right, sing, sing(upper) 상태로 1초를 2의 속도로 이동중인 상태 유지.
	--2. (32초 ~ 34초) : A, C그룹 1초에 8타일을 움직이는 속도로 right, sing, dance(upper) 시작.
	--2초 경과하면 제자리에서 속도 1초에 2타일로 변경한 후 현상태 유지.
	--3. (33초 ~ 35초) : B 그룹 1초에 8타일을 움직이는 속도로 right, sing, dance(upper) 시작.
	--2초 경과하면 제자리에서 속도 1초에 2타일로 변경한 후 현상태 유지.
	--4. (34초 ~ 36초) : D, E그룹 1초에 8타일을 움직이는 속도로 right, sing, dance(upper) 시작.
	--2초 경과하면 제자리에서 속도 1초에 2타일로 변경한 후 현상태 유지.
	--5. (35초 ~ 37초) : F그룹 1초에 8타일을 움직이는 속도로 right, sing, dance(upper) 시작.
	--2초 경과하면 제자리에서 속도 1초에 2타일로 변경한 후 현상태 유지.

	--6. (37.5초) : E 그룹 현재 위치에 left, smile, get 자세 실행 후 정지.
	--7. (38초) : A, D 그룹 현재 위치에 left, smile, get 자세 실행 후 정지.
	--8. (40초) : F, C그룹 현재 위치에 right, smile, get 자세 실행 후 정지.
	--9. (40.5초) : C 그룹 현재 위치에 right, smile, get 자세 실행 후 정지.
	--10. (43.5초 ~ 44초) : E 0.5초간 플라워가 배치된 파이프에 right, smile, hide_in(임시 : jump)를 실행.
	--1타일 우측에 착지하여 down, idle, hide(임시 : prostrate) 실행 후 유지.
	--11. (44초 ~ 44.5초) : A, D 0.5초간 플라워가 배치된 파이프에 right, smile, hide_in(임시 : jump)를 실행.
	--1타일 우측에 착지하여 down, idle, hide(임시 : prostrate) 실행 후 유지.
	--12. (46초 ~ 46.5초) : C, F 0.5초간 플라워가 배치된 파이프에 right, smile, hide_in(임시 : jump)를 실행.
	--1타일 우측에 착지하여 down, idle, hide(임시 : prostrate) 실행 후 유지.
	--13. (47초 ~ 47.5초) : B 0.5초간 플라워가 배치된 파이프에 right, smile, hide_in(임시 : jump)를 실행.
	--1타일 우측에 착지하여 down, idle, hide(임시 : prostrate) 실행 후 유지.
	local result = util.merge_patterns(patterns)

	util.add_delay_to_group(result.game, args.common.start_delay)

	return result
end

local cached_patterns = {}

return {
	generate = function(key)
		if cached_patterns[key] == nil then
			local args = pattern_args[key]

			cached_patterns[key] = create_pattern(args)
		end

		return cached_patterns[key]
	end
}

