local create_pattern = function(args)
	local patterns = {}

	--1. 최초 파이프 위치에 그룹 A ~ D down, idle, hide(임시 : prostrate) 상태로 배치됨.
	for group_key, info in pairs(args.groups) do
		local characters = {}

		local group_name = 'pipe_move_' .. group_key

		for i = 1, #info.offsets do
			local name = group_name .. '_' .. i

			characters[i] = name
		end

		local init = {
			create_clip_bundle(-1, nil, {
				create_sub_clip('character.group.register', {
					characters = characters,
					spec_name = 'flower'
				}),

				generate_sub_clip_by_function('character.single.offset', characters, function(key, value)
					return {
						name = value,
						offset = info.offsets[key]
					}
				end),
				scene_bundle_generator.sub.create_group_hide_init(characters, group_name),
			}),
		}

		local move_start_bit = info.start_bit_offset + info.move_info.start_delays[1]
		local move_end_bit = info.start_bit_offset + info.move_info.end_delay

		--2. (51.5초 ~ 58.5초) : A 그룹 플라워 right, smile, hide_out을 실행하여 0.5초 안에 1타일 우측으로 이동.
		--해당 그룹은 도착한 위치에서 right, smile, sing(upper) 우측으로 1타일을 1초에 이동하는 속도로 진행한 후,
		--도착한 이 과정에서 아래의 타이밍마다 지정된 상황을 실행.
		--55초 시점에 A 그룹 하단 방향으로 3타일을 1초에 안에 움직인다.
		--이후 58초가 되면 A 그룹 플라워 right, smile, hide_in를 0.5초간 실행한 후,
		--도착하면 현재 위치에서 down, idle, hide 상태로 변경 후 유지.
		local game = {
			scene_bundle_generator.bundle.create_group_pop_out(info.start_bit_offset, move_start_bit,
					characters, group_name .. '_land'),
			create_clip(move_start_bit, move_end_bit, 'character.group.set_async', {
				characters = characters,
				set_common = {
					emotion = 'sing',
					anim = { name = 'sing', upper = true }
				},
				reset_common = {
					remove_anim_type = type_const.remove_anim_type.upper,
					remove_emotion = true,
				}
			}),
		}

		for i = 1, #info.move_info.start_delays do
			local local_start_bit = info.start_bit_offset + info.move_info.start_delays[i]
			local local_end_bit = info.start_bit_offset + (info.move_info.start_delays[i + 1] or info.move_info.end_delay)

			game[#game + 1] = create_clip_bundle(local_start_bit, local_end_bit, {
				create_sub_clip('character.group.move', {
					characters = characters,
					waypoints = {
						group_name .. '_move_' .. i
					},
					use_walk = true,
				})
			})
		end

		game[#game + 1] = scene_bundle_generator.bundle.create_group_hide_in(
				move_end_bit, info.start_bit_offset + info.end_delay,
				characters, group_name .. '_end')

		local dispose = {
			scene_bundle_generator.bundle.create_group_dispose(characters),
		}

		patterns[group_key] = {
			init = init,
			game = game,
			dispose = dispose,
		}
	end

	local result = util.merge_patterns(patterns)

	util.add_delay_to_group(result.game, args.common.start_delay)

	return result
end

local cached_patterns = {}

return {
	generate = function(key)
		if cached_patterns[key] == nil then
			local args = pattern_args[key]

			cached_patterns[key] = create_pattern(args)
		end

		return cached_patterns[key]
	end
}

