local group = {
	---@param bit_args { start_bit, hold_up_duration, bomb_move_duration, bomb_spawn_duration }
	---@param character_args { name, throw_direction }
	---@param bomb_args { name, spawn_position, hold_up_position, fall_position, explosion_radius }
	---@param etc_args { attack_range_preset_key, fx_preset_key }
	create_throw_bomb = function(bit_args, character_args, bomb_args, etc_args, repeat_count)
		local cycle_bit_duration = bit_args.hold_up_duration + bit_args.bomb_move_duration + bit_args.bomb_spawn_duration
		local result = {}

		local add = function(data)
			result[#result + 1] = data
		end

		for i = 1, repeat_count do
			local delayed_bit = (i - 1) * cycle_bit_duration
			local start_bit = delayed_bit + bit_args.start_bit
			local hold_up_end_bit = start_bit + bit_args.hold_up_duration
			local move_start_bit = hold_up_end_bit
			local explode_bit = move_start_bit + bit_args.bomb_move_duration
			local spawn_start_bit = explode_bit
			local spawn_end_bit = spawn_start_bit + bit_args.bomb_spawn_duration

			--0초 ~ 0.5초 : 지정된 지점에 어택 레인지 생성 + A ~ G 의 플라워들
			--우측 폭탄꽃에 배치된 폭탄을 right, smile, hold로 들어올림.
			add(create_clip_bundle(start_bit, hold_up_end_bit, {
				create_sub_clip('character.single.set_async', {
					name = character_args.name,
					set = {
						direction = 'right',
						anim = { name = 'hold', loop = false, one_shot_sfx = false },
					},
					reset = {
						remove_anim_type = type_const.remove_anim_type.normal,
					}
				}),

				create_sub_clip('field_object.bomb.move', {
					name = bomb_args.name,
					position = bomb_args.hold_up_position,
				}),
			}))

			add(create_clip(start_bit, explode_bit, 'attack_range.show', {
				preset_key = etc_args.attack_range_preset_key,
				position = bomb_args.fall_position,
			}))

			--0.5초 ~ 1초 : Y축 상단에서부터 지정된 지점까지 낙하함.
			--A ~ G 의 플라워들 홀드한 폭탄을 붉은색 자신의 알파벳 지점을 향해 0.5초의 시간동안 던져지도록 함.
			add(create_clip_bundle(move_start_bit, explode_bit, {
				create_sub_clip('character.single.set', {
					name = character_args.name,
					direction = character_args.throw_direction,
					anim = { name = 'throw', count = 1 },
				}),

				create_sub_clip('field_object.bomb.move', {
					name = bomb_args.name,
					position = bomb_args.fall_position,
					sine_move_max_height = 2,
				}),
			}))

