					preset_key = etc_args.fx_preset_key,
					position = bomb_args.fall_position,
				}),

				create_sub_clip('field_object.bomb.dispose', {
					name = bomb_args.name,
					position = bomb_args.fall_position,
					explosion_radius = bomb_args.explosion_radius,
				}),

				create_sub_clip('audio.sfx.one_shot', {
					name = '01_arcade_explosion_01'
				})
			}))

			--1초 ~ 1.5초 : 폭탄 도착한 뒤, 폭파 후 1.5초가 될 때까지 대기
			--대기 시간동안 폭탄꽃에 폭탄 스케일 상승하며 생성됨.
			add(create_clip(explode_bit, spawn_end_bit, 'field_object.bomb.instantiate', {
				name = bomb_args.name,
				position = bomb_args.spawn_position,
			}))
		end

		return result
	end,
}

